def clamp_force(value):
    return float(np.clip(value, *RANGE_N))

def _linear(feature, mean, scale, weight):
    return clamp_force(weight[0] + np.dot(weight[1:], (feature - mean) / scale))

def estimate_force(delta_raw):
    """Return (fz_n, region_weights, confidence, best_region).

    A normalized 24-channel direction softly selects all four calibrated regions.
    When a response lies outside the sampled-region envelope, a global model is
    blended in progressively instead of returning an abrupt 0 N.
    """
    feature = np.asarray(delta_raw, dtype=float).reshape(-1)
    if feature.size != 24 or not np.all(np.isfinite(feature)):
        raise ValueError("NO8 estimator requires 24 finite RAW Delta-B values")
    norm = float(np.linalg.norm(feature))
    if norm < 1500.0:
        return 0.0, np.full(4, 0.25), 0.0, 0
    candidates = np.asarray([_linear(feature, MODEL_MEAN[i], MODEL_SCALE[i], MODEL_WEIGHT[i]) for i in range(4)])
    scores = PROTOTYPE @ (feature / norm)
    logits = 12.0 * (scores - float(np.max(scores)))
    region_weights = np.exp(logits)
    region_weights /= float(region_weights.sum())
    regional = float(np.dot(region_weights, candidates))
    global_force = _linear(feature, GLOBAL_MEAN, GLOBAL_SCALE, GLOBAL_WEIGHT)
    confidence = float(np.clip((float(np.max(scores)) - 0.65) / (0.85 - 0.65), 0.0, 1.0))
    force = clamp_force(confidence * regional + (1.0 - confidence) * global_force)
    return force, region_weights, confidence, int(np.argmax(region_weights))
